    10	public class Database {
    11	    private static HikariDataSource dataSource;
    12	
    13	    public static void init() {
    14	        String dbUrl = System.getenv("DB_URL");
    15	        String dbUser = System.getenv("DB_USER");
    16	        String dbPassword = System.getenv("DB_PASSWORD");
    17	
    18	        if (dbUrl == null || dbUser == null || dbPassword == null) {
    19	            throw new RuntimeException("DB_URL, DB_USER, and DB_PASSWORD environment variables are required");
    20	        }
    21	
    22	        HikariConfig config = new HikariConfig();
    23	        config.setJdbcUrl(dbUrl);
    24	        config.setUsername(dbUser);
    25	        config.setPassword(dbPassword);
    26	        config.setMaximumPoolSize(10);
    27	
    28	        dataSource = new HikariDataSource(config);
    29	
    30	        createTables();
    31	        initializeRooms();
    32	    }
    33	
    34	    private static void createTables() {
    35	        try (Connection conn = dataSource.getConnection();
    36	             Statement stmt = conn.createStatement()) {
    37	
    38	            stmt.execute("""
    39	                CREATE TABLE IF NOT EXISTS rooms (
    40	                    number INTEGER PRIMARY KEY,
    41	                    type VARCHAR(50) NOT NULL,
    42	                    capacity INTEGER NOT NULL,
    43	                    nightly_rate NUMERIC(10, 2) NOT NULL
    44	                )
    45	            """);
    46	
    47	            stmt.execute("""
    48	                CREATE TABLE IF NOT EXISTS reservations (
    49	                    id SERIAL PRIMARY KEY,
    50	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
    51	                    guest_name VARCHAR(255) NOT NULL,
    52	                    guest_email VARCHAR(255) NOT NULL,
    53	                    guest_cpf VARCHAR(20) NOT NULL,
    54	                    check_in DATE NOT NULL,
    55	                    check_out DATE NOT NULL,
    56	                    guests INTEGER NOT NULL,
    57	                    rate_plan VARCHAR(50) NOT NULL,
    58	                    nights INTEGER NOT NULL,
    59	                    subtotal NUMERIC(10, 2) NOT NULL,
    60	                    discount NUMERIC(10, 2) NOT NULL,
    61	                    total NUMERIC(10, 2) NOT NULL,
    62	                    status VARCHAR(50) NOT NULL,
    63	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    64	                    refund NUMERIC(10, 2)
    65	                )
    66	            """);
    67	
    68	            stmt.execute("""
    69	                CREATE TABLE IF NOT EXISTS messages (
    70	                    id SERIAL PRIMARY KEY,
    71	                    channel VARCHAR(50) NOT NULL,
    72	                    "to" VARCHAR(255) NOT NULL,
    73	                    subject VARCHAR(255) NOT NULL,
    74	                    body TEXT NOT NULL,
    75	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    76	                )
    77	            """);
    78	        } catch (SQLException e) {
    79	            throw new RuntimeException("Failed to create tables", e);
    80	        }
    81	    }
    82	
    83	    private static void initializeRooms() {
    84	        try (Connection conn = dataSource.getConnection();
    85	             Statement stmt = conn.createStatement()) {
    86	
    87	            var rs = stmt.executeQuery("SELECT COUNT(*) as count FROM rooms");
    88	            rs.next();
    89	            if (rs.getInt("count") == 0) {
    90	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
    91	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
    92	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
    93	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
    94	                stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
    95	            }
    96	        } catch (SQLException e) {
    97	            throw new RuntimeException("Failed to initialize rooms", e);
    98	        }
    99	    }
   100	
   101	    public static Connection getConnection() throws SQLException {
   102	        return dataSource.getConnection();
   103	    }
   104	
   105	    public static void close() {
   106	        if (dataSource != null) {
   107	            dataSource.close();
   108	        }
   109	    }
   110	}
