     1	package com.pousada;
     2	
     3	import io.javalin.http.HttpStatus;
     4	
     5	import java.sql.*;
     6	import java.time.LocalDate;
     7	
     8	public class ReservationService {
     9	    public static Reservation create(CreateReservationRequest req) {
    10	        try {
    11	            LocalDate checkIn = DateUtils.parseIsoDate(req.checkIn);
    12	            LocalDate checkOut = DateUtils.parseIsoDate(req.checkOut);
    13	
    14	            if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    15	                throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_REQUEST", "Check-out deve ser após check-in");
    16	            }
    17	
    18	            if (req.guests < 1) {
    19	                throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_REQUEST", "Deve ter pelo menos 1 hóspede");
    20	            }
    21	
    22	            Room room = RoomService.findByNumber(req.roomNumber);
    23	            if (room == null) {
    24	                throw new ApiException(HttpStatus.NOT_FOUND, "ROOM_NOT_FOUND", "Quarto não encontrado");
    25	            }
    26	
    27	            if (req.guests > room.capacity) {
    28	                throw new ApiException(422, "CAPACITY_EXCEEDED", "Quarto comporta menos hóspedes");
    29	            }
    30	
    31	            if (isRoomUnavailable(req.roomNumber, checkIn, checkOut)) {
    32	                throw new ApiException(HttpStatus.CONFLICT, "ROOM_UNAVAILABLE", "Quarto não disponível nesse período");
    33	            }
    34	
    35	            RatePlan ratePlan = RatePlan.fromString(req.ratePlan);
    36	            var prices = PriceCalculator.calculate(checkIn, checkOut, room.nightlyRate, ratePlan);
    37	
    38	            try (Connection conn = Database.getConnection()) {
    39	                String query = String.format(
    40	                    "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) " +
    41	                    "VALUES (%d, '%s', '%s', '%s', '%s', '%s', %d, '%s', %d, %.2f, %.2f, %.2f, '%s', 0) RETURNING id",
    42	                    req.roomNumber,
    43	                    escapeString(req.guestName),
    44	                    escapeString(req.guestEmail),
    45	                    escapeString(req.guestCpf),
    46	                    req.checkIn,
    47	                    req.checkOut,
    48	                    req.guests,
    49	                    ratePlan.toString(),
    50	                    prices.nights,
    51	                    prices.subtotal,
    52	                    prices.discount,
    53	                    prices.total,
    54	                    ReservationStatus.PENDING.toString()
    55	                );
    56	
    57	                try (Statement stmt = conn.createStatement()) {
    58	                    ResultSet rs = stmt.executeQuery(query);
    59	                    rs.next();
    60	                    int id = rs.getInt("id");
    61	                    return findById(id);
    62	                }
    63	            }
    64	        } catch (ApiException e) {
    65	            throw e;
    66	        } catch (Exception e) {
    67	            throw new RuntimeException("Error creating reservation", e);
    68	        }
    69	    }
    70	
    71	    public static Reservation confirm(int id, double amountPaid) {
    72	        try {
    73	            Reservation res = findById(id);
    74	            if (res == null) {
    75	                throw new ApiException(HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
    76	            }
    77	            if (!res.status.equals(ReservationStatus.PENDING.toString())) {
    78	                throw new ApiException(HttpStatus.CONFLICT, "OPERATION_NOT_ALLOWED", "Reserva deve estar pendente para confirmar");
    79	            }
    80	
    81	            try (Connection conn = Database.getConnection();
    82	                 Statement stmt = conn.createStatement()) {
    83	                stmt.execute(String.format(
    84	                    "UPDATE reservations SET status = '%s', amount_paid = %.2f WHERE id = %d",
    85	                    ReservationStatus.CONFIRMED.toString(),
    86	                    amountPaid,
    87	                    id
    88	                ));
    89	            }
    90	
    91	            var updated = findById(id);
    92	            sendConfirmationEmail(updated);
    93	            return updated;
    94	        } catch (ApiException e) {
    95	            throw e;
    96	        } catch (Exception e) {
    97	            throw new RuntimeException("Error confirming reservation", e);
    98	        }
    99	    }
   100	
   101	    public static Reservation checkIn(int id) {
   102	        try {
   103	            Reservation res = findById(id);
   104	            if (res == null) {
   105	                throw new ApiException(HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   106	            }
   107	            if (!res.status.equals(ReservationStatus.CONFIRMED.toString())) {
   108	                throw new ApiException(HttpStatus.CONFLICT, "OPERATION_NOT_ALLOWED", "Reserva deve estar confirmada para check-in");
   109	            }
   110	
   111	            try (Connection conn = Database.getConnection();
   112	                 Statement stmt = conn.createStatement()) {
   113	                stmt.execute(String.format(
   114	                    "UPDATE reservations SET status = '%s' WHERE id = %d",
   115	                    ReservationStatus.CHECKED_IN.toString(),
   116	                    id
   117	                ));
   118	            }
   119	
   120	            return findById(id);
   121	        } catch (ApiException e) {
   122	            throw e;
   123	        } catch (Exception e) {
   124	            throw new RuntimeException("Error checking in reservation", e);
   125	        }
   126	    }
   127	
   128	    public static ReservationDocument checkOut(int id) {
   129	        try {
   130	            Reservation res = findById(id);
   131	            if (res == null) {
   132	                throw new ApiException(HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   133	            }
   134	            if (!res.status.equals(ReservationStatus.CHECKED_IN.toString())) {
   135	                throw new ApiException(HttpStatus.CONFLICT, "OPERATION_NOT_ALLOWED", "Reserva deve estar com check-in para fazer check-out");
   136	            }
   137	
   138	            try (Connection conn = Database.getConnection();
   139	                 Statement stmt = conn.createStatement()) {
   140	                stmt.execute(String.format(
   141	                    "UPDATE reservations SET status = '%s' WHERE id = %d",
   142	                    ReservationStatus.CHECKED_OUT.toString(),
   143	                    id
   144	                ));
   145	            }
   146	
   147	            return getDocument(id);
   148	        } catch (ApiException e) {
   149	            throw e;
   150	        } catch (Exception e) {
   151	            throw new RuntimeException("Error checking out reservation", e);
   152	        }
   153	    }
   154	
   155	    public static Reservation cancel(int id) {
   156	        try {
   157	            Reservation res = findById(id);
   158	            if (res == null) {
   159	                throw new ApiException(HttpStatus.NOT_FOUND, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   160	            }
   161	            if (!res.status.equals(ReservationStatus.PENDING.toString()) && !res.status.equals(ReservationStatus.CONFIRMED.toString())) {
   162	                throw new ApiException(HttpStatus.CONFLICT, "OPERATION_NOT_ALLOWED", "Cancela nada é permitida apenas antes do check-in");
   163	            }
   164	
   165	            double refund = 0;
   166	            if (res.status.equals(ReservationStatus.CONFIRMED.toString())) {
   167	                RatePlan ratePlan = RatePlan.fromString(res.ratePlan);
   168	                if (ratePlan == RatePlan.STANDARD) {
   169	                    refund = res.amountPaid;
   170	                }
   171	            }
   172	
   173	            try (Connection conn = Database.getConnection();
   174	                 Statement stmt = conn.createStatement()) {
   175	                stmt.execute(String.format(
   176	                    "UPDATE reservations SET status = '%s', refund = %.2f WHERE id = %d",
   177	                    ReservationStatus.CANCELLED.toString(),
   178	                    refund,
   179	                    id
   180	                ));
   181	            }
   182	
   183	            return findById(id);
   184	        } catch (ApiException e) {
   185	            throw e;
   186	        } catch (Exception e) {
   187	            throw new RuntimeException("Error canceling reservation", e);
   188	        }
   189	    }
   190	
   191	    public static Reservation findById(int id) {
   192	        try (Connection conn = Database.getConnection();
   193	             Statement stmt = conn.createStatement()) {
   194	            ResultSet rs = stmt.executeQuery("SELECT * FROM reservations WHERE id = " + id);
   195	            if (rs.next()) {
   196	                return new Reservation(
   197	                    rs.getInt("id"),
   198	                    rs.getInt("room_number"),
   199	                    rs.getString("guest_name"),
   200	                    rs.getString("guest_email"),
   201	                    rs.getString("guest_cpf"),
   202	                    rs.getString("check_in"),
   203	                    rs.getString("check_out"),
   204	                    rs.getInt("guests"),
   205	                    rs.getString("rate_plan"),
   206	                    rs.getInt("nights"),
   207	                    rs.getDouble("subtotal"),
   208	                    rs.getDouble("discount"),
   209	                    rs.getDouble("total"),
   210	                    rs.getString("status"),
   211	                    rs.getDouble("amount_paid"),
   212	                    rs.getObject("refund") != null ? rs.getDouble("refund") : null
   213	                );
   214	            }
   215	        } catch (SQLException e) {
   216	            throw new RuntimeException("Error fetching reservation", e);
   217	        }
   218	        return null;
   219	    }
   220	
   221	    public static ReservationDocument getDocument(int id) {
   222	        try {
   223	            Reservation res = findById(id);
   224	            if (res == null) {
   225	                return null;
   226	            }
   227	            if (!res.status.equals(ReservationStatus.CONFIRMED.toString()) &&
   228	                !res.status.equals(ReservationStatus.CHECKED_IN.toString()) &&
   229	                !res.status.equals(ReservationStatus.CHECKED_OUT.toString())) {
   230	                return null;
   231	            }
   232	
   233	            Room room = RoomService.findByNumber(res.roomNumber);
   234	            return new ReservationDocument(
   235	                res.id,
   236	                res.guestName,
   237	                res.guestCpf,
   238	                res.roomNumber,
   239	                room.type,
   240	                res.checkIn,
   241	                res.checkOut,
   242	                res.nights,
   243	                res.subtotal,
   244	                res.discount > 0 ? res.discount : null,
   245	                res.total
   246	            );
   247	        } catch (Exception e) {
   248	            throw new RuntimeException("Error getting document", e);
   249	        }
   250	    }
   251	
   252	    private static boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   253	        try (Connection conn = Database.getConnection();
   254	             Statement stmt = conn.createStatement()) {
   255	            String query = String.format(
   256	                "SELECT COUNT(*) as count FROM reservations " +
   257	                "WHERE room_number = %d " +
   258	                "AND status != '%s' " +
   259	                "AND check_in < '%s' " +
   260	                "AND check_out > '%s'",
   261	                roomNumber,
   262	                ReservationStatus.CANCELLED.toString(),
   263	                checkOut,
   264	                checkIn
   265	            );
   266	            ResultSet rs = stmt.executeQuery(query);
   267	            rs.next();
   268	            return rs.getInt("count") > 0;
   269	        } catch (SQLException e) {
   270	            throw new RuntimeException("Error checking room availability", e);
   271	        }
   272	    }
   273	
   274	    private static void sendConfirmationEmail(Reservation res) {
   275	        var doc = getDocument(res.id);
   276	        if (doc == null) return;
   277	
   278	        String body = formatConfirmationEmail(doc);
   279	        MessageService.sendEmail(res.guestEmail, "Reserva confirmada - Pousada Maré Alta", body);
   280	    }
   281	
   282	    private static String formatConfirmationEmail(ReservationDocument doc) {
   283	        return String.format(
   284	            "Olá, %s!\n\n" +
   285	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   286	            "%s\n\n" +
   287	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   288	            "Até breve!",
   289	            doc.guestName,
   290	            formatDocument(doc)
   291	        );
   292	    }
   293	
   294	    public static String formatDocument(ReservationDocument doc) {
   295	        String nightsLabel = doc.nights == 1 ? "1 diária" : doc.nights + " diárias";
   296	        StringBuilder sb = new StringBuilder();
   297	        sb.append("Comprovante de reserva nº ").append(doc.reservationId).append("\n");
   298	        sb.append("Hóspede: ").append(doc.guestName).append(" (CPF ").append(doc.guestCpf).append(")\n");
   299	        sb.append("Quarto: ").append(doc.roomNumber).append(" (").append(doc.roomType).append(")\n");
   300	        sb.append("Entrada: ").append(DateUtils.formatDisplay(DateUtils.parseIsoDate(doc.checkIn)))
   301	          .append(" | Saída: ").append(DateUtils.formatDisplay(DateUtils.parseIsoDate(doc.checkOut)))
   302	          .append(" | ").append(nightsLabel).append("\n");
   303	        sb.append("Diárias: ").append(Money.formatBRL(doc.subtotal)).append("\n");
   304	        if (doc.discount != null && doc.discount > 0) {
   305	            sb.append("Desconto: ").append(Money.formatBRL(doc.discount)).append("\n");
   306	        }
   307	        sb.append("Total: ").append(Money.formatBRL(doc.total));
   308	        return sb.toString();
   309	    }
   310	
   311	    private static String escapeString(String value) {
   312	        return value.replace("'", "''").replace("\\", "\\\\");
   313	    }
   314	}

