    41	                    "VALUES (%d, '%s', '%s', '%s', '%s', '%s', %d, '%s', %d, %.2f, %.2f, %.2f, '%s', 0) RETURNING id",
    42	                    req.roomNumber,
    43	                    escapeString(req.guestName),
    44	                    escapeString(req.guestEmail),
    45	                    escapeString(req.guestCpf),
    46	                    req.checkIn,
