     1	package com.pousada;
     2	
     3	import java.time.LocalDate;
     4	
     5	public class PriceCalculator {
     6	    public static class PriceBreakdown {
     7	        public int nights;
     8	        public double subtotal;
     9	        public double discount;
    10	        public double total;
    11	
    12	        public PriceBreakdown(int nights, double subtotal, double discount, double total) {
    13	            this.nights = nights;
    14	            this.subtotal = subtotal;
    15	            this.discount = discount;
    16	            this.total = total;
    17	        }
    18	    }
    19	
    20	    public static PriceBreakdown calculate(LocalDate checkIn, LocalDate checkOut, double nightlyRate, RatePlan ratePlan) {
    21	        int nights = DateUtils.countNights(checkIn, checkOut);
    22	
    23	        if (nights < 1) {
    24	            throw new IllegalArgumentException("Check-out must be after check-in");
    25	        }
    26	
    27	        double subtotal = 0;
    28	        LocalDate currentDate = checkIn;
    29	        while (currentDate.isBefore(checkOut)) {
    30	            double dailyRate = nightlyRate;
    31	            if (DateUtils.isHighSeason(currentDate)) {
    32	                dailyRate = Money.round(dailyRate * 1.2);
    33	            }
    34	            subtotal = Money.round(subtotal + dailyRate);
    35	            currentDate = currentDate.plusDays(1);
    36	        }
    37	
    38	        double discount = 0;
    39	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    40	            discount = Money.round(subtotal * 0.15);
    41	        }
    42	
    43	        double total = Money.round(subtotal - discount);
    44	
    45	        return new PriceBreakdown(nights, subtotal, discount, total);
    46	    }
    47	}
